package net.spell_engine.internals.casting;

import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.util.Identifier;
import net.spell_engine.api.spell.event.SpellEvents;
import net.spell_engine.api.spell.registry.SpellRegistry;
import net.spell_engine.internals.cost.Ammo;

/// The gate in front of every cast attempt (cooldown, ammo, injected event verdicts), run on
/// the server before starting or performing a spell, and on the client before a cast request is
/// even sent. Starting/ending the casting process is {@link SpellCastInteractor}'s job; what
/// happens when the process completes (or ticks, for channels) is
/// {@link net.spell_engine.internals.SpellExecution}'s job.
public class SpellCasting {

    // MARK: Cast attempt

    public static SpellCast.Attempt attempt(PlayerEntity player, ItemStack itemStack, Identifier spellId) {
        return attempt(player, itemStack, spellId, true);
    }

    /// The gate in front of every cast, run on the server before starting or performing a spell, and
    /// on the client before a cast request is even sent. Composes the cooldown and ammo checks with
    /// the PRE/POST attempt events mods can inject a verdict through.
    public static SpellCast.Attempt attempt(PlayerEntity player, ItemStack itemStack, Identifier spellId, boolean checkAmmo) {
        var caster = (SpellCaster.Player)player;
        var spellEntry = SpellRegistry.from(player.getWorld()).getEntry(spellId).orElse(null);
        if (spellEntry == null) {
            return SpellCast.Attempt.none();
        }
        var spell = spellEntry.value();
        if (SpellEvents.CASTING_ATTEMPT.PRE.isListened()) {
            var args = new SpellEvents.CastingAttemptEvent.Args(player, spellEntry, itemStack);
            var injected = SpellEvents.CASTING_ATTEMPT.PRE.invokeWithResult(listener -> listener.onCastingAttempt(args));
            if (injected != null) {
                return injected;
            }
        }
        if (caster.getCooldownManager().isCoolingDown(spellEntry)) {
            return SpellCast.Attempt.failOnCooldown(new SpellCast.Attempt.OnCooldownInfo());
        }
        if (checkAmmo) {
            var ammoResult = Ammo.ammoForSpell(player, spell, itemStack);
            if (!ammoResult.satisfied()) {
                return SpellCast.Attempt.failMissingItem(new SpellCast.Attempt.MissingItemInfo(ammoResult.item()));
            }
        }
        if (SpellEvents.CASTING_ATTEMPT.POST.isListened()) {
            var args = new SpellEvents.CastingAttemptEvent.Args(player, spellEntry, itemStack);
            var injected = SpellEvents.CASTING_ATTEMPT.POST.invokeWithResult(listener -> listener.onCastingAttempt(args));
            if (injected != null) {
                return injected;
            }
        }
        return SpellCast.Attempt.success();
    }
}

package net.spell_engine.internals.cost;
import net.spell_engine.Platform;

import com.google.common.collect.Maps;
import net.minecraft.entity.Entity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.registry.entry.RegistryEntry;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.util.Identifier;
import net.minecraft.util.math.MathHelper;
import net.spell_engine.api.spell.Spell;
import net.spell_engine.network.Packets;
import org.jetbrains.annotations.Nullable;

import java.util.Iterator;
import java.util.List;
import java.util.Map;

public class SpellCooldownManager {
    public record Entry(int startTick, int endTick) {
        int timeLeft(int currentTick) {
            return Math.max(0, endTick - currentTick);
        }
    }
    private final Map<Identifier, Entry> entries = Maps.newHashMap();
    private int tick;

    private final Entity owner;

    public SpellCooldownManager(Entity owner) {
        this.owner = owner;
    }

    public void tickUpdate() {
        ++this.tick;
        this.update(true);
    }

    @Nullable private static Identifier groupId(Spell spell) {
        if (spell.cost.cooldown != null) {
            var group = spell.cost.cooldown.group;
            if (group != null) {
                return Identifier.of("group", group);
            }
        }
        return null;
    }

    public boolean isCoolingDown(RegistryEntry<Spell> spell) {
        return this.getCooldownProgress(spell, 0.0f) > 0.0f;
    }

    @Deprecated
    protected boolean isCoolingDown(Identifier spell) {
        return this.getCooldownProgress(spell, 0.0f) > 0.0f;
    }

    public float getCooldownProgress(RegistryEntry<Spell> spell, float tickDelta) {
        var id = spell.getKey().get().getValue();
        var groupId = groupId(spell.value());
        if (groupId == null) {
            return this.getCooldownProgress(id, tickDelta);
        } else {
            return Math.max(
                    this.getCooldownProgress(id, tickDelta),
                    this.getCooldownProgress(groupId, tickDelta)
            );
        }
    }

    protected float getCooldownProgress(Identifier spell, float tickDelta) {
        SpellCooldownManager.Entry entry = this.entries.get(spell);
        if (entry != null) {
            float f = entry.endTick - entry.startTick;
            float g = (float)entry.endTick - ((float)this.tick + tickDelta);
            return MathHelper.clamp(g / f, 0.0f, 1.0f);
        }
        return 0.0f;
    }

    public int getCooldownDuration(RegistryEntry<Spell> spell) {
        var id = spell.getKey().get().getValue();
        var groupId = groupId(spell.value());
        if (groupId == null) {
            return this.getCooldownDuration(id);
        } else {
            return Math.max(
                    this.getCooldownDuration(id),
                    this.getCooldownDuration(groupId)
            );
        }
    }

    protected int getCooldownDuration(Identifier spell) {
        SpellCooldownManager.Entry entry = this.entries.get(spell);
        if (entry != null) {
            return entry.timeLeft(this.tick);
        }
        return 0;
    }

    public void setDurationLeft(RegistryEntry<Spell> spell, int duration) {
        var spellId = spell.getKey().get().getValue();
        this.setDurationLeft(spellId, duration);
        var groupId = groupId(spell.value());
        if (groupId != null) {
            this.setDurationLeft(groupId, duration);
        }
    }

    protected void setDurationLeft(Identifier spell, int duration) {
        var existingEntry = this.entries.get(spell);
        if (existingEntry != null) {
            this.entries.put(spell, new Entry(this.tick, this.tick + duration));
        } else if (duration > 0) {
            this.entries.put(spell, new Entry(this.tick, this.tick + duration));
        }
    }

    public void update(boolean sync) {
        if (!this.entries.isEmpty()) {
            Iterator<Map.Entry<Identifier, Entry>> iterator = this.entries.entrySet().iterator();
            while (iterator.hasNext()) {
                Map.Entry<Identifier, Entry> entry = iterator.next();
                if (entry.getValue().endTick > this.tick) continue;
                iterator.remove();
                if (sync) {
                    this.cooldownCleared(entry.getKey());
                }
            }
        }
    }

    public void set(RegistryEntry<Spell> spell, int duration) {
        this.set(spell, duration, true);
    }

    public void set(RegistryEntry<Spell> spell, int duration, boolean force) {
        var spellId = spell.getKey().get().getValue();
        this.set(spellId, duration, force);
        var groupId = groupId(spell.value());
        if (groupId != null) {
            this.set(groupId, duration, force);
        }
    }

    protected void set(Identifier spell, int duration, boolean force) {
        if (force
                || !this.entries.containsKey(spell)
                || (this.entries.get(spell).timeLeft(tick) < duration)
        ) {
            this.entries.put(spell, new Entry(this.tick, this.tick + duration));
            this.cooldownSet(spell, duration);
        }
    }

    @Deprecated
    private void set(Identifier spell, int duration) {
        this.set(spell, duration, true);
    }

    public void remove(Identifier spell) {
        this.entries.remove(spell);
        this.cooldownCleared(spell);
    }

    protected void cooldownSet(Identifier spell, int duration) {
        if (owner instanceof ServerPlayerEntity serverPlayer) {
            Platform.util().networkS2C_Send(serverPlayer, new Packets.SpellCooldown(spell, duration));
        }
    }

    protected void cooldownCleared(Identifier spell) {
        if (owner instanceof ServerPlayerEntity serverPlayer) {
            Platform.util().networkS2C_Send(serverPlayer, new Packets.SpellCooldown(spell, 0));
        }
    }

    private static final String NBT_KEY = "spell_engine_cooldowns";
    public void writeCustomDataToNbt(NbtCompound nbt) {
        NbtCompound cooldowns = new NbtCompound();
        for (var entry: entries.entrySet()) {
            var spell = entry.getKey();
            var cooldown = entry.getValue();
            NbtCompound cooldownData = new NbtCompound();
            cooldownData.putInt("start", cooldown.startTick - tick);
            cooldownData.putInt("end", cooldown.endTick - tick);
            cooldowns.put(spell.toString(), cooldownData);
        }
        nbt.put(NBT_KEY, cooldowns);
    }

    public void readCustomDataFromNbt(NbtCompound nbt) {
        NbtCompound cooldowns = nbt.getCompound(NBT_KEY);
        for (var key: cooldowns.getKeys()) {
            var spell = Identifier.of(key);
            var cooldownData = cooldowns.getCompound(key);
            var start = cooldownData.getInt("start");
            var end = cooldownData.getInt("end");
            entries.put(spell, new Entry(start, end));
        }
    }

    public void reset(@Nullable Identifier spellId) {
        if (spellId == null) {
            entries.clear();
        } else {
            entries.remove(spellId);
        }
        pushSync();
    }

    public void pushSync() {
        if (owner instanceof ServerPlayerEntity serverPlayer) {
            Platform.util().networkS2C_Send(serverPlayer, new Packets.SpellCooldownSync(this.tick, Map.copyOf(this.entries)));
        }
    }

    public void acceptSync(int baseTick, Map<Identifier, Entry> cooldowns) {
        this.tick = baseTick;
        this.entries.clear();
        this.entries.putAll(cooldowns);
    }

    public List<Identifier> spellsOnCooldown() {
        return this.entries.keySet().stream().toList();
    }
}

package net.spell_engine.internals.cost;

import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.registry.entry.RegistryEntry;
import net.spell_engine.SpellEngineMod;
import net.spell_engine.api.spell.Spell;
import net.spell_engine.api.tags.SpellEngineItemTags;
import net.spell_engine.internals.SpellParameters;
import net.spell_engine.internals.casting.SpellCaster;
import net.spell_engine.internals.container.SpellContainerSource;
import net.spell_engine.utils.ItemCooldownManagerExtension;

/// Imposing spell cooldowns as part of a cast's cost: the spell's own cooldown (tracked by
/// {@link SpellCooldownManager}), plus the optional item-level lock on the hosting item.
public class SpellCooldowns {

    public static void imposeCooldown(PlayerEntity player, SpellContainerSource.SourcedContainer source, RegistryEntry<Spell> spellEntry, float progress) {
        var spell = spellEntry.value();
        var duration = cooldownToSet(player, spellEntry, progress);
        var durationTicks = Math.round(duration * 20F);
        if (duration > 0) {
            ((SpellCaster.Player) player).getCooldownManager().set(spellEntry, durationTicks);
        }
        if (SpellEngineMod.config.spell_item_cooldown_lock && spell.cost.cooldown.hosting_item && source.itemStack() != null) {
            var hostingItem = source.itemStack().getItem();
            var itemCooldowns = player.getItemCooldownManager();
            if (source.itemStack().isIn(SpellEngineItemTags.SPELL_BOOK)) {
                durationTicks += (int) (SpellEngineMod.config.spell_book_additional_cooldown * 20F);
            }
            var durationLeft = ((ItemCooldownManagerExtension)itemCooldowns).SE_getLastCooldownDuration(hostingItem)
                    * itemCooldowns.getCooldownProgress(hostingItem, 0);
            if (durationTicks > durationLeft) {
                itemCooldowns.set(hostingItem, durationTicks);
            }
        }
    }

    private static float cooldownToSet(LivingEntity caster, RegistryEntry<Spell> spellEntry, float progress) {
        var spell = spellEntry.value();
        if (spell.cost.cooldown.proportional) {
            return SpellParameters.getCooldownDuration(caster, spellEntry) * progress;
        } else {
            return SpellParameters.getCooldownDuration(caster, spellEntry);
        }
    }

    /// The `attempt_duration` cooldown, set at the moment a delivery is attempted (as opposed to the
    /// full cooldown above, which is only imposed once the delivery reports success).
    public static void imposeAttemptCooldown(PlayerEntity player, RegistryEntry<Spell> spellEntry) {
        var spell = spellEntry.value();
        if (spell.cost.cooldown != null) {
            var attemptCooldown = spell.cost.cooldown.attempt_duration;
            if (attemptCooldown > 0) {
                var durationTicks = Math.round(attemptCooldown * 20F);
                ((SpellCaster.Player) player).getCooldownManager().set(spellEntry, durationTicks);
            }
        }
    }
}

package net.spell_engine.internals.cost;

import net.minecraft.entity.EquipmentSlot;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.registry.Registries;
import net.minecraft.registry.entry.RegistryEntry;
import net.minecraft.util.Identifier;
import net.spell_engine.SpellEngineMod;
import net.spell_engine.api.spell.Spell;
import net.spell_engine.api.spell.event.SpellEvents;
import net.spell_engine.internals.casting.SpellBatcher;
import net.spell_engine.internals.container.SpellContainerSource;
import net.spell_engine.utils.WorldScheduler;

/// The [COST] stage: everything a successful cast consumes — cooldown, exhaust, durability,
/// ammo/rune items, and cost status effects. Runs from the delivery completion callback, so a
/// delivery that never landed costs nothing (see SpellExecution's flow map).
public class SpellCost {

    public static void consume(PlayerEntity player, float progress, SpellContainerSource.SourcedContainer spellSource, Identifier spellId, RegistryEntry<Spell> spellEntry, ItemStack heldItemStack, Ammo.Result ammoResult, boolean scheduled) {
        var spell = spellEntry.value();
        var batching = spell.cost.batching;
        if (batching && !scheduled) {
            if (((SpellBatcher)player).hasBatchedCost(spellId)) {
                return;
            }
            ((WorldScheduler)player.getWorld()).schedule(0, () -> consume(player, progress, spellSource, spellId, spellEntry, heldItemStack, ammoResult, true));
            ((SpellBatcher)player).batchCost(spellId, true);
            return;
        }

        // Consume things
        // Cooldown
        SpellCooldowns.imposeCooldown(player, spellSource, spellEntry, progress);
        // Exhaust
        player.addExhaustion(spell.cost.exhaust * SpellEngineMod.config.spell_cost_exhaust_multiplier);
        // Durability
        if (SpellEngineMod.config.spell_cost_durability_allowed && spell.cost.durability > 0) {
            var stackToDamage = (spellSource.itemStack() != null && spellSource.itemStack().isDamageable()) ? spellSource.itemStack() : heldItemStack;
            stackToDamage.damage(spell.cost.durability, player, EquipmentSlot.MAINHAND);
        }
        // Item
        Ammo.consume(ammoResult, player);
        // Status effect
        if (spell.cost.effect_id != null) {
            var effect = Registries.STATUS_EFFECT.getEntry(Identifier.of(spell.cost.effect_id));
            if (effect.isPresent()) {
                player.removeStatusEffect(effect.get());
            }
        }
        if (SpellEvents.COST_CONSUME.isListened()) {
            var args = new SpellEvents.SpellCostConsumeEvent.Args(player, spellEntry, heldItemStack);
            SpellEvents.COST_CONSUME.invoke(l -> l.onSpellCostConsume(args));
        }
    }
}

package net.spell_engine.mixin.entity;

import net.minecraft.entity.data.DataTracker;
import net.minecraft.entity.data.TrackedData;
import net.minecraft.entity.data.TrackedDataHandlerRegistry;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.registry.entry.RegistryEntry;
import net.spell_engine.api.spell.Spell;
import net.spell_engine.client.animation.AnimatablePlayer;
import net.spell_engine.internals.delivery.arrow.ArrowShootContext;
import net.spell_engine.internals.casting.SpellCastInteractor;
import net.spell_engine.utils.Binding;
import net.spell_engine.internals.casting.SpellCaster;
import net.spell_engine.internals.casting.SpellCasterEntity;
import net.spell_engine.internals.cost.SpellCooldownManager;
import net.spell_engine.internals.delivery.melee.Melee;
import org.jetbrains.annotations.Nullable;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;

import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;


@Mixin(value = PlayerEntity.class, priority = 555)
// Implements the DEPRECATED bridge type (extends SpellCaster.Player) on purpose: external
// compat mods cast players to SpellCasterEntity — the cast only works if players implement it.
public class PlayerEntityMixin implements SpellCaster.Player, SpellCasterEntity {

    private PlayerEntity player() {
        return (PlayerEntity) ((Object) this);
    }

    private final SpellCooldownManager spellCooldownManager = new SpellCooldownManager(player());

    /// The casting authority component. The two bindings lens its synced state (process,
    /// options) onto the tracked data slots below: the server writes through them, the client
    /// reads through them (the interactor parses lazily on change — no polling here).
    private final SpellCastInteractor interactor = SpellCastInteractor.forPlayer(player(),
            new Binding<>(
                    () -> player().getDataTracker().get(SPELL_ENGINE_SPELL_PROGRESS),
                    json -> {
                        if (!player().getWorld().isClient) {
                            player().getDataTracker().set(SPELL_ENGINE_SPELL_PROGRESS, json);
                        }
                    }),
            new Binding<>(
                    () -> player().getDataTracker().get(SPELL_ENGINE_OPTIONS),
                    json -> {
                        if (!player().getWorld().isClient) {
                            player().getDataTracker().set(SPELL_ENGINE_OPTIONS, json);
                        }
                    }));

    @Override
    public SpellCastInteractor getInteractor() {
        return interactor;
    }

    private static final TrackedData<String> SPELL_ENGINE_SPELL_PROGRESS = DataTracker.registerData(PlayerEntity.class, TrackedDataHandlerRegistry.STRING);
    private static final TrackedData<String> SPELL_ENGINE_OPTIONS = DataTracker.registerData(PlayerEntity.class, TrackedDataHandlerRegistry.STRING);
    private static final TrackedData<Float> SPELL_ENGINE_EXTRA_SLIPPERINESS = DataTracker.registerData(PlayerEntity.class, TrackedDataHandlerRegistry.FLOAT);

    @Inject(method = "initDataTracker", at = @At("TAIL"))
    private void initDataTracker_TAIL_SpellEngine_SyncEffects(DataTracker.Builder builder, CallbackInfo ci) {
        builder.add(SPELL_ENGINE_SPELL_PROGRESS, "");
        builder.add(SPELL_ENGINE_OPTIONS, "");
        builder.add(SPELL_ENGINE_EXTRA_SLIPPERINESS, 0F);
    }

    private ArrowShootContext arrowShotContext = ArrowShootContext.empty();
    @Override
    public void setArrowShootContext(ArrowShootContext shotContext) {
        arrowShotContext = shotContext;
    }
    @Override
    public ArrowShootContext getArrowShootContext() {
        return arrowShotContext;
    }

    @Override
    public SpellCooldownManager getCooldownManager() {
        return spellCooldownManager;
    }

    @Inject(method = "tick", at = @At("TAIL"))
    public void tick_TAIL_SpellEngine(CallbackInfo ci) {
        var player = player();
        if (player.getWorld().isClient) {
            ((AnimatablePlayer)player()).updateSpellCastAnimationsOnTick();
        } else {
            // Server side
            interactor.tick();
            if (activeAttack_serverSide != null
                    // Offsetting time by 1 tick, to compensate sync delays
                    && activeAttack_serverSide.isFinished(player.age + 1)) {
                setMeleeSkillAttack(null);
            }
        }
        spellCooldownManager.tickUpdate();
    }

    private Melee.ActiveAttack activeAttack_serverSide = null;
    @Override
    public void setMeleeSkillAttack(Melee.ActiveAttack attack) {
        activeAttack_serverSide = attack;
        float slip = 0;
        if (attack != null) {
            slip = attack.attack.movement_slip();
        }
        player().getDataTracker().set(SPELL_ENGINE_EXTRA_SLIPPERINESS, slip);
    }
    @Override
    public float getExtraSlipperiness() {
        return player().getDataTracker().get(SPELL_ENGINE_EXTRA_SLIPPERINESS);
    }

    @Nullable private RegistryEntry<Spell> activeMeleeSpell = null;
    public void setActiveMeleeSkill(RegistryEntry<Spell> spell) {
        activeMeleeSpell = spell;
    }
    public RegistryEntry<Spell> getActiveMeleeSkill() {
        return activeMeleeSpell;
    }

    // MARK: Persistence

    @Inject(method = "writeCustomDataToNbt", at = @At("TAIL"))
    public void writeCustomDataToNbt_TAIL_SpellEngine(NbtCompound nbt, CallbackInfo ci) {
        spellCooldownManager.writeCustomDataToNbt(nbt);
    }

    @Inject(method = "readCustomDataFromNbt", at = @At("TAIL"))
    public void readCustomDataFromNbt_TAIL_SpellEngine(NbtCompound nbt, CallbackInfo ci) {
        spellCooldownManager.readCustomDataFromNbt(nbt);
    }
}

package net.spell_engine.network;

import com.google.common.collect.Iterables;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.server.world.ServerWorld;
import net.spell_engine.SpellEngineMod;
import net.spell_engine.internals.casting.SpellCaster;
import net.spell_engine.internals.container.SpellContainerSource;
import net.spell_engine.internals.delivery.melee.Melee;


/// Server-side packet handling. This class is loader-agnostic: it holds only the handler
/// bodies. Payload registration, configuration tasks and the lifecycle event wiring live in
/// each loader's own network entrypoint (`FabricServerNetwork` / NeoForge `NetworkEvents`),
/// which forwards decoded packets here.
public class ServerNetwork {
    // Configuration-task identifiers. Shared so the client-side Ack and both loaders' task
    // implementations agree on the same names.
    public static final String CONFIG_TASK_NAME = SpellEngineMod.ID + ":" + "config";
    public static final String SPELL_REGISTRY_TASK_NAME = SpellEngineMod.ID + ":" + "spell_registry";

    // MARK: Casting protocol — signals into the caster's SpellCastInteractor

    public static void handleCastRequest(Packets.CastRequest packet, MinecraftServer server, ServerPlayerEntity player) {
        ServerWorld world = Iterables.tryFind(server.getWorlds(), (element) -> element == player.getWorld())
                .orNull();
        if (world == null || world.isClient) {
            return;
        }
        world.getServer().executeSync(() -> {
            ((SpellCaster.Player) player).getInteractor().requestCast(packet.spellId(), packet.snapshot());
        });
    }

    public static void handleTargetStream(Packets.TargetStream packet, MinecraftServer server, ServerPlayerEntity player) {
        ServerWorld world = Iterables.tryFind(server.getWorlds(), (element) -> element == player.getWorld())
                .orNull();
        if (world == null || world.isClient) {
            return;
        }
        world.getServer().executeSync(() -> {
            ((SpellCaster.Player) player).getInteractor().submitTargets(packet.spellId(), packet.snapshot());
        });
    }

    public static void handleCastInput(Packets.CastInput packet, MinecraftServer server, ServerPlayerEntity player) {
        ServerWorld world = Iterables.tryFind(server.getWorlds(), (element) -> element == player.getWorld())
                .orNull();
        if (world == null || world.isClient) {
            return;
        }
        world.getServer().executeSync(() -> {
            ((SpellCaster.Player) player).getInteractor().requestEnd(packet.spellId(), packet.snapshot());
        });
    }

    public static void handleAttackFxBroadcast(Packets.AttackFxBroadcast packet, MinecraftServer server, ServerPlayerEntity player) {
        ServerWorld world = Iterables.tryFind(server.getWorlds(), (element) -> element == player.getWorld())
                .orNull();
        if (world == null || world.isClient) {
            return;
        }

        world.getServer().executeSync(() -> {
            Melee.broadcastAttackFx(player, packet.attackContext());
        });
    }

    public static void handleAttackPerform(Packets.AttackPerform packet, MinecraftServer server, ServerPlayerEntity player) {
        ServerWorld world = Iterables.tryFind(server.getWorlds(), (element) -> element == player.getWorld())
                .orNull();
        if (world == null || world.isClient) {
            return;
        }

        world.getServer().executeSync(() -> {
            Melee.performAttackAgainstTargets(player, packet.attackContext(), packet.targetIds());
        });
    }

    /// Invoked when a player joins or changes dimension: re-sync their spell cooldowns and
    /// server-side spell containers. Wired to `ServerPlayConnectionEvents.JOIN` /
    /// `ServerEntityWorldChangeEvents` on Fabric and to `PlayerEvent` on NeoForge.
    public static void onPlayerConnectOrChangeWorld(ServerPlayerEntity player) {
        ((SpellCaster.Player) player).getCooldownManager().pushSync();
        SpellContainerSource.syncServerSideContainers(player);
    }
}
